"use strict";
// 题目难度档（1–5）的统一标准。所有让 AI 评难度的地方（题库评定、导入、会话里逐题记录、结算、错题重做）都用这里的文字。
//
// 依据：教育部考试中心衡量试题难度的口径是「难度＝考生平均得分 / 满分」（得分率）；
// 研招网转载的命题解读把 0.3–0.8 视为中等、0.3 以下为难题、0.8 以上为易题，中等题占八成以上；
// 历年数学一全卷平均得分率约 0.44（2019 年考试中心公布 65.69/150）。
// 题目本身的「内容难度」在数学教育测量里常按：知识点个数与综合程度、推理步骤、运算量、方法是否常规、题型新颖度来判断。
// 所以这里的五档直接对应「全国考研考生在这道题上的预计得分率」，并给出判断因素和真卷位置的校准参照。
// 能力模型里 b = 档 − 3：一个水平正好在全国平均的考生，做 1–5 档的预计做对率约 88% / 73% / 50% / 27% / 12%，和下面的得分率区间对得上。

const RUBRIC_VER = 2;

const LEVELS = [
  { d: 1, name: "基础", rate: "≥ 80%", desc: "直接套一个定义、公式或结论，一两步出结果；人人练过的题型" },
  { d: 2, name: "简单", rate: "60–80%", desc: "常规题型，方法一眼看出，两三步或少量计算；基本只考一个考点" },
  { d: 3, name: "中档", rate: "40–60%", desc: "要选对方法、避开一个陷阱，或计算量较大；涉及一两个考点。考研选择填空和常规解答题的大多数" },
  { d: 4, name: "较难", rate: "20–40%", desc: "综合两三个考点、步骤长，或要做一次不明显的转化（换元、构造辅助函数、分类讨论），或要写完整证明" },
  { d: 5, name: "压轴", rate: "< 20%", desc: "需要构造或较深的思路、几个难点叠加；多数考生拿不到一半分" },
];

/** 一行版（工具参数说明、会话规则里用）。 */
const RUBRIC_SHORT = `难度档 1–5 按「全国考研考生在这道题上的预计得分率」评，看的是题目本身、不是学习者做得怎样：${LEVELS.map((l) => `${l.d} ${l.name}（${l.rate}）＝${l.desc.split("；")[0]}`).join("；")}`;

/** 完整版（批量评定、导入、结算用）。 */
const RUBRIC_FULL = `难度档 1–5 的标准：设想这道题出现在当年的考研试卷上，**全国考生在这道题上的平均得分率**大约是多少（教育部考试中心衡量试题难度就用「平均得分 / 满分」）。
${LEVELS.map((l) => `${l.d} ${l.name}：得分率 ${l.rate}。${l.desc}。`).join("\n")}

判断时依次看五个因素，「高」的因素越多档越高：
① 知识点：只用一个考点，还是跨两三个考点 / 跨章综合；
② 步骤：一两步、三五步，还是要长链推理；
③ 运算量：口算级、常规计算，还是繁琐易错的计算；
④ 方法：一眼可见的套路，还是要换元、构造、分类讨论、反证等不明显的转化；
⑤ 新颖度与陷阱：常见题型，还是条件隐蔽、有易错陷阱、题型少见。

校准参照（真卷的大致规律，按题目实际内容可以上下浮动一档）：
- 数学：全卷平均得分率历年约四成五，所以 3 中档应该是最多的一档，4–5 合计约两成，1 只给纯套公式的题。选择 / 填空前几题多为 1–2，中间多 2–3，陷阱多或计算量大的到 4；解答题前一两道多为 3，中间 3–4，最后一两道（证明、综合）4–5。线性代数、概率的解答题多为 3–4。
- 408：选择题多为 2–3，少数概念细节或计算绕的到 4；综合应用题（41–47）多为 3–4，算法设计题和组成原理综合题多为 4，个别 5。
- 英语：完形和新题型多为 2–3；阅读按推理深度和干扰项强度 2–4；翻译、作文按得分率多为 3。
- 政治：单选多为 2，多选多为 3；分析题 3。
- 习题书：印了星级的以星级为主要参考（★→1–2，★★→2，★★★→3，★★★★ 及以上→4）；基础篇 / 660 起点 2，强化篇 / 综合篇起点 3，再按上面的因素调整。
- 会话里只截取了原题的一步、或给了提示的，按实际要做的那一步来评。`;

module.exports = { RUBRIC_VER, LEVELS, RUBRIC_SHORT, RUBRIC_FULL };
